-- Restore Battle on the High Seas (map 1099, scenarios 182/239).
-- Spawn and text data were ported read-only from Legends of Azeroth
-- Pandaria 5.4.8 (build 18414); scripts were adapted to Legion 7.3.5.
-- Legion build 26972 DB2 confirms both faction scenarios, criteria trees, and normal/heroic LFG entries.
START TRANSACTION;

-- Replace the empty/partial population with the coherent MoP scenario population.
DELETE `ca` FROM `creature_addon` `ca` INNER JOIN `creature` `c` ON `c`.`guid`=`ca`.`guid` WHERE `c`.`map`=1099;
DELETE `wp` FROM `waypoint_data` `wp` INNER JOIN `creature` `c` ON `c`.`guid`=`wp`.`id` WHERE `c`.`map`=1099;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`memberGUID` WHERE `c`.`map`=1099;
DELETE `cf` FROM `creature_formations` `cf` INNER JOIN `creature` `c` ON `c`.`guid`=`cf`.`leaderGUID` WHERE `c`.`map`=1099;
DELETE `gec` FROM `game_event_creature` `gec` INNER JOIN `creature` `c` ON `c`.`guid`=`gec`.`guid` WHERE `c`.`map`=1099;
DELETE `pc` FROM `pool_creature` `pc` INNER JOIN `creature` `c` ON `c`.`guid`=`pc`.`guid` WHERE `c`.`map`=1099;
DELETE `geg` FROM `game_event_gameobject` `geg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`geg`.`guid` WHERE `go`.`map`=1099;
DELETE `pg` FROM `pool_gameobject` `pg` INNER JOIN `gameobject` `go` ON `go`.`guid`=`pg`.`guid` WHERE `go`.`map`=1099;
DELETE FROM `creature` WHERE `map`=1099;
DELETE FROM `gameobject` WHERE `map`=1099;



